using Microsoft.Win32;using SaarOSS.Rechnungsprogramm.Services;using System.Diagnostics;using System.IO;using System.Windows;using System.Windows.Controls;
namespace SaarOSS.Rechnungsprogramm.Views;
public partial class UpdateCenterView:UserControl
{
 readonly UpdateZipService service=new();UpdateZipService.UpdateManifest? manifest;string? selectedZip;UpdateZipService.VerifiedPackage? verified;
 public UpdateCenterView(){InitializeComponent();InstalledVersionText.Text=UpdateZipService.InstalledVersion;}
 async void CheckOnline(object s,RoutedEventArgs e){await Run(async()=>{manifest=await service.GetManifestAsync();OnlineInfoText.Text=$"Version {manifest.Version}\nVer\u00F6ffentlicht: {manifest.Published}\nGr\u00F6\u00DFe: {manifest.SizeText}\n{manifest.Notes}";DownloadButton.IsEnabled=service.IsNewer(manifest.Version);StatusText.Text=DownloadButton.IsEnabled?"Ein neues Update ist verf\u00FCgbar.":"Die installierte Version ist aktuell.";});}
 async void DownloadZip(object s,RoutedEventArgs e){if(manifest is null)return;await Run(async()=>{selectedZip=await service.DownloadAsync(manifest,p=>StatusText.Text=$"Download: {p}%");SelectedFileText.Text=selectedZip;VerifyButton.IsEnabled=true;StatusText.Text="Update-ZIP heruntergeladen. Die Installation wurde nicht gestartet.";});}
 void SelectZip(object s,RoutedEventArgs e){var d=new OpenFileDialog{Filter="SaarOSS-Update (*.zip)|*.zip",Title="Heruntergeladenes Update-ZIP ausw\u00E4hlen"};if(d.ShowDialog()==true){selectedZip=d.FileName;verified=null;SelectedFileText.Text=selectedZip;PackageInfoText.Text="Noch nicht gepr\u00FCft.";VerifyButton.IsEnabled=true;InstallButton.IsEnabled=false;}}
 async void VerifyZip(object s,RoutedEventArgs e){if(selectedZip is null)return;await Run(async()=>{verified=await service.VerifyAsync(selectedZip,manifest);PackageInfoText.Text=$"Version: {verified.Version}\nSHA-256: {verified.Sha256}\nDateien: {verified.FileCount}\nHauptordner: {verified.RootFolder}";InstallButton.IsEnabled=true;StatusText.Text="Updatepaket erfolgreich gepr\u00FCft.";});}
 void InstallZip(object s,RoutedEventArgs e){if(verified is null)return;if(MessageBox.Show("Das Hauptprogramm wird geschlossen. Vor dem Dateiaustausch wird eine vollst\u00E4ndige Programmsicherung erstellt. Update jetzt einspielen?","Update best\u00E4tigen",MessageBoxButton.YesNo,MessageBoxImage.Warning)!=MessageBoxResult.Yes)return;try{service.StartExternalUpdater(verified);Application.Current.Shutdown();}catch(Exception ex){MessageBox.Show(ex.Message,"Update konnte nicht gestartet werden",MessageBoxButton.OK,MessageBoxImage.Error);}}
 void OpenDownloads(object s,RoutedEventArgs e){Directory.CreateDirectory(service.DownloadFolder);Process.Start(new ProcessStartInfo("explorer.exe",service.DownloadFolder){UseShellExecute=true});}
 async Task Run(Func<Task> action){try{StatusText.Text="Bitte warten ...";await action();}catch(Exception ex){StatusText.Text="Fehler: "+ex.Message;MessageBox.Show(ex.Message,"Update-Center",MessageBoxButton.OK,MessageBoxImage.Error);}}
}